  // 模块别名（共用词表：同一套取象在不同模块口径下只是章法不同，事物分类一致）
  var MOD_TERMS_ALIAS = { job: 'career', loveF: 'loveM' };
  function modTable(modId) {
    var id = MOD_TERMS_ALIAS[modId] || modId;
    return MOD_XIANG[id] || GENERIC_XIANG;   // 无专属表 → 通用三层（person/fweek/fyear/misc/num/general）
  }
  function modTableName(modId) {
    var id = MOD_TERMS_ALIAS[modId] || modId;
    return (MOD_XIANG[id] || GENERIC_XIANG);
  }

  // 力量档 → 数字（取象二次赋值用；与引擎 lvOfScore 的档位名一一对应，避免文字歧义）
  var POWER_SLOT = { 极旺: 5, 旺相: 4, 有气: 3, 中性: 2, 衰弱: 1, 极衰: 0 };

  // 爻位 → 数字（初=1…上=6，直接取引擎 y.idx，此处只作缺省兜底）
  function posSlot(y) {
    if (!y) return 0;
    if (typeof y.idx === 'number' && y.idx >= 1 && y.idx <= 6) return y.idx;
    return y.pos || 0;
  }

